const fs = require('node:fs')
const path = require('node:path')
const file = path.join(process.cwd(), 'notify.json')
let calls = []
try {
  calls = JSON.parse(fs.readFileSync(file, 'utf8'))
} catch {}
module.exports = {
  notify(options, callback) {
    calls.push({ ...options, message: options.message.replace(/^(\u2705|\u26D4\uFE0F) /, '') })
    fs.writeFileSync(file, JSON.stringify(calls))
    if (callback) callback(null, '', {})
  },
}
